// Normalize evaluation or field-run evidence into one stable decision.
const s = <%0%>;
const status = String(s.status ?? "unknown");
const stopReason = String(s.stop_reason ?? "");
const completed = Number(s.completed_observations ?? 0);
const remaining = Number(s.remaining_observations ?? 0);
const total = Number(s.total_observations ?? (completed + remaining));
const hasGateEvidence = s.gate5_evidence === true;
const complete = status === "complete" && remaining === 0;
const resumable =
  s.resumable === true ||
  status === "paused" ||
  (s.last_result && s.last_result.resumable === true);

let decision = "REVIEW";
let nextAction = "Inspect the status, direct evidence, and unresolved blockers before another mutation.";

if (complete && hasGateEvidence) {
  decision = "ACCEPT_EVIDENCE";
  nextAction = "Archive the evidence and fingerprints, then proceed to the next approved field task.";
} else if (status === "blocked") {
  decision = "INVESTIGATE_GATE";
  nextAction = "Inspect the failed gate and criterion-level evidence; do not weaken thresholds or rerun blindly.";
} else if (resumable || remaining > 0) {
  decision = "RESUME_CHECKPOINT";
  nextAction = "Resume the same frozen checkpoint with the same model, rubric, corpus, and settings.";
} else if (status === "error") {
  decision = "DIAGNOSE_INFRASTRUCTURE";
  nextAction = "Classify the infrastructure failure before retrying; preserve all completed evidence.";
}

return {
  schema_version: 1,
  decision,
  complete,
  gate5_evidence: hasGateEvidence,
  resumable,
  status,
  stop_reason: stopReason,
  completed_observations: completed,
  remaining_observations: remaining,
  total_observations: total,
  next_action: nextAction,
  summary:
    decision +
    ": " +
    completed +
    "/" +
    total +
    " observations complete; remaining=" +
    remaining +
    "; stop_reason=" +
    (stopReason || "none")
};
